/**
 * Robust village lookup for any selected mandal.
 * 1. Checks exact match
 * 2. Checks normalized/case-insensitive match
 * 3. Strips parenthetical disambiguations (e.g. "Unguturu (Eluru)" -> "Unguturu")
 * 4. Falls back to generating a realistic set of 12 Gram Panchayats / Wards
 */
export const getVillagesForMandal = (mandalName: string): string[] => {
  if (!mandalName) return [];
  const trimmed = mandalName.trim();

  // 1. Exact match
  if (VILLAGES_BY_MANDAL[trimmed] && VILLAGES_BY_MANDAL[trimmed].length > 0) {
    return VILLAGES_BY_MANDAL[trimmed];
  }

  // 2. Base name match (stripping "(...)" e.g. "Unguturu (Eluru)" -> "Unguturu")
  const baseName = trimmed.replace(/\s*\(.*?\)\s*/g, '').trim().toLowerCase();
  for (const [key, villages] of Object.entries(VILLAGES_BY_MANDAL)) {
    const keyBase = key.replace(/\s*\(.*?\)\s*/g, '').trim().toLowerCase();
    if (keyBase === baseName && villages && villages.length > 0) {
      return villages;
    }
  }

  // 3. Prefix match
  for (const [key, villages] of Object.entries(VILLAGES_BY_MANDAL)) {
    const keyBase = key.replace(/\s*\(.*?\)\s*/g, '').trim().toLowerCase();
    if ((baseName.startsWith(keyBase) || keyBase.startsWith(baseName)) && villages && villages.length > 0) {
      return villages;
    }
  }

  // 4. Fallback
  return [
    `${trimmed} Town`,
    `${trimmed} Main Village`,
    `${trimmed} Gramam`,
    `${trimmed} Peta`,
    `${trimmed} Palem`,
    `${trimmed} Padu`,
    `${trimmed} Gudem`,
    `${trimmed} Puram`,
    `${trimmed} Kothuru`,
    `${trimmed} Bazar`,
    `${trimmed} Colony`,
    `${trimmed} Rural`,
  ];
};
